/**
 * n8n Code node — Workflow B
 * Parse config tab once and store for all parallel ranking branches.
 * Wire: Read config tab B -> Store ranking config -> Validate config -> Read unique_jobs tab
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function cleanResume(value) {
  return String(value ?? '').trim();
}

function normalizeKey(raw) {
  return clean(raw)
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}

function isHeaderRow(key, value) {
  const k = normalizeKey(key);
  const v = normalizeKey(value);
  return (k === 'key' && (v === 'value' || v === '')) || (k === 'config_key' && v === 'config_value');
}

function looksLikeConfigKey(text) {
  const t = normalizeKey(text);
  return t.length > 0 && t.length < 80 && /^[a-z][a-z0-9_]*$/.test(t);
}

function shouldKeepMultilineValue(key) {
  const k = clean(key).toLowerCase();
  return k.includes('resume') || k.includes('prompt') || k === 'jd_score_prompt';
}

function extractPair(json) {
  const obj = json || {};

  if (obj.key !== undefined && obj.key !== null && String(obj.key).trim()) {
    const key = clean(String(obj.key));
    const raw = obj.value;
    if (raw !== undefined && raw !== null && String(raw).trim()) {
      const value = shouldKeepMultilineValue(key) ? cleanResume(raw) : clean(raw);
      return { key, value };
    }
  }

  const skip = new Set(['row_number', 'row', 'id']);
  const keyCandidates = [
    'key', 'Key', 'KEY', 'config_key', 'name', 'setting', 'parameter',
    'A', 'Column A', 'col_1', 'column_1',
  ];
  const valueCandidates = [
    'value', 'Value', 'VALUE', 'config_value', 'content', 'text',
    'B', 'Column B', 'col_2', 'column_2',
  ];

  let key = '';
  let value = '';

  for (const field of keyCandidates) {
    if (obj[field] !== undefined && obj[field] !== null && String(obj[field]).trim()) {
      key = clean(obj[field]);
      break;
    }
  }

  for (const field of valueCandidates) {
    if (obj[field] !== undefined && obj[field] !== null && String(obj[field]).trim()) {
      const raw = obj[field];
      value = shouldKeepMultilineValue(key) ? cleanResume(raw) : clean(raw);
      break;
    }
  }

  if (key && value) {
    if (key.length > 500 && value.length < 120 && looksLikeConfigKey(value)) {
      return { key: value, value: key };
    }
    return { key, value };
  }

  const entries = Object.entries(obj)
    .filter(([name, val]) => !skip.has(name) && val !== undefined && val !== null && clean(val))
    .map(([name, val]) => [name, clean(val)]);

  if (entries.length >= 2) {
    const [a, b] = entries;
    const aIsKey = looksLikeConfigKey(a[1]);
    const bIsKey = looksLikeConfigKey(b[1]);
    if (aIsKey && !bIsKey) return { key: a[1], value: b[1] };
    if (bIsKey && !aIsKey) return { key: b[1], value: a[1] };
    return { key: a[1], value: b[1] };
  }

  if (entries.length === 1) {
    const [name, val] = entries[0];
    if (looksLikeConfigKey(name)) return { key: name, value: val };
    if (looksLikeConfigKey(val)) return { key: val, value: '' };
  }

  return { key: '', value: '' };
}

function buildConfigMap(rows) {
  const map = {};

  for (const item of rows) {
    const { key, value } = extractPair(item.json || {});
    if (!key || isHeaderRow(key, value)) continue;

    const nk = normalizeKey(key);
    if (!nk) continue;

    const existing = map[nk] || '';
    if (value && (!existing || value.length > existing.length)) {
      map[nk] = value;
    }
  }

  return map;
}

function getConfigRows() {
  try {
    const sheetRows = $('Read config tab B').all();
    if (sheetRows.length) return sheetRows;
  } catch (error) {}

  return $input.all();
}

function pick(map, keys) {
  for (const key of keys) {
    const nk = normalizeKey(key);
    if (map[nk]) return map[nk];
  }
  for (const key of keys) {
    const wanted = normalizeKey(key);
    const fuzzy = Object.keys(map).find((k) => k.includes(wanted) || wanted.includes(k));
    if (fuzzy && map[fuzzy]) return map[fuzzy];
  }
  return '';
}

const rows = getConfigRows();
const map = buildConfigMap(rows);
const staticData = $getWorkflowStaticData('global');

staticData.rankingConfig = {
  openai_api_key: pick(map, ['openai_api_key']),
  openai_model: pick(map, ['openai_model']) || 'gpt-4o-mini',
  jd_score_prompt: pick(map, ['jd_score_prompt']),
  systems_rank_prompt: pick(map, ['systems_rank_prompt']),
  mechanical_rank_prompt: pick(map, ['mechanical_rank_prompt']),
  controls_rank_prompt: pick(map, ['controls_rank_prompt']),
  systems_resume_text: pick(map, [
    'systems_resume_text',
    'systems_resume',
    'system_resume_text',
  ]),
  mechanical_resume_text: pick(map, [
    'mechanical_resume_text',
    'mechanical_resume',
    'mech_resume_text',
  ]),
  controls_resume_text: pick(map, [
    'controls_resume_text',
    'controls_resume',
    'control_resume_text',
  ]),
  blocklist: pick(map, ['blocklist']),
};

const loadedKeys = Object.keys(map);
const firstRow = rows[0]?.json || {};
const resumeKeyLengths = loadedKeys
  .filter((k) => k.includes('resume'))
  .map((k) => `${k}=${(map[k] || '').length}`)
  .join(', ');

return [{
  json: {
    config_loaded: true,
    config_rows: rows.length,
    config_rows_from_input: $input.all().length,
    config_pairs_parsed: loadedKeys.length,
    has_jd_score_prompt: Boolean(staticData.rankingConfig.jd_score_prompt),
    has_systems_resume: Boolean(staticData.rankingConfig.systems_resume_text),
    has_mechanical_resume: Boolean(staticData.rankingConfig.mechanical_resume_text),
    has_controls_resume: Boolean(staticData.rankingConfig.controls_resume_text),
    config_keys_seen: loadedKeys.slice(0, 40).join(', '),
    debug_first_row_fields: Object.keys(firstRow).join(', '),
    debug_resume_key_lengths: resumeKeyLengths || 'no keys containing resume in config tab',
    jd_score_prompt_chars: String(staticData.rankingConfig.jd_score_prompt || '').length,
    systems_resume_chars: String(staticData.rankingConfig.systems_resume_text || '').length,
    mechanical_resume_chars: String(staticData.rankingConfig.mechanical_resume_text || '').length,
    controls_resume_chars: String(staticData.rankingConfig.controls_resume_text || '').length,
  },
}];

/**
 * n8n Code node — Workflow B
 * Fail fast with a clear message if resumes are missing.
 * Wire: Store ranking config -> Validate config -> Read unique_jobs tab
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function cleanResume(value) {
  return String(value ?? '').trim();
}

function normalizeKey(raw) {
  return clean(raw)
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}

function getStoreOutput() {
  try {
    return $('Store ranking config').first().json || {};
  } catch (error) {
    return {};
  }
}

/** Re-load resumes from sheet if staticData is empty (safety net). */
function reloadRankingConfigFromSheet() {
  const map = {};

  try {
    for (const item of $('Read config tab B').all()) {
      const json = item.json || {};
      const key = clean(String(json.key || ''));
      const raw = json.value;
      if (!key || key.toLowerCase() === 'key') continue;
      if (raw === undefined || raw === null || !String(raw).trim()) continue;

      const nk = normalizeKey(key);
      const value = key.toLowerCase().includes('resume') ? cleanResume(raw) : clean(raw);
      if (value && (!map[nk] || value.length > map[nk].length)) {
        map[nk] = value;
      }
    }
  } catch (error) {
    return null;
  }

  if (!Object.keys(map).length) return null;

  const staticData = $getWorkflowStaticData('global');
  staticData.rankingConfig = {
    ...(staticData.rankingConfig || {}),
    openai_model: map.openai_model || staticData.rankingConfig?.openai_model || 'gpt-4o-mini',
    systems_resume_text: map.systems_resume_text || '',
    mechanical_resume_text: map.mechanical_resume_text || '',
    controls_resume_text: map.controls_resume_text || '',
    blocklist: map.blocklist || staticData.rankingConfig?.blocklist || '',
  };

  return staticData.rankingConfig;
}

let cfg = $getWorkflowStaticData('global').rankingConfig || {};
const storeOutput = getStoreOutput();

const required = [
  'systems_resume_text',
  'mechanical_resume_text',
  'controls_resume_text',
];

let missing = required.filter((key) => !String(cfg[key] || '').trim());

if (missing.length) {
  const reloaded = reloadRankingConfigFromSheet();
  if (reloaded) {
    cfg = reloaded;
    missing = required.filter((key) => !String(cfg[key] || '').trim());
  }
}

if (missing.length) {
  const keysSeen = clean(storeOutput.config_keys_seen || '');
  const resumeLikeKeys = keysSeen
    .split(',')
    .map((key) => clean(key))
    .filter((key) => key.includes('resume'));

  throw new Error(
    `Config tab is missing resume text for: ${missing.join(', ')}.\n\n` +
    'Your sheet input looks correct (row_number, key, value). Usually this means:\n' +
    '- systems_resume_text or mechanical_resume_text rows are empty in column B, OR\n' +
    '- Store ranking config Code node is set to "Run once for each item" (change to "Run once for all items")\n\n' +
    'Check **Store ranking config** output:\n' +
    `- config_rows: ${storeOutput.config_rows || 0} (should be ~20+)\n` +
    `- config_rows_from_input: ${storeOutput.config_rows_from_input || '?'}\n` +
    `- debug_resume_key_lengths: ${storeOutput.debug_resume_key_lengths || 'none'}\n` +
    `- controls_resume_chars: ${storeOutput.controls_resume_chars || 0}\n\n` +
    `Resume keys parsed: ${resumeLikeKeys.join(', ') || 'none'}\n` +
    'Re-import PipelineB.json and run from Start Workflow B.'
  );
}

return [{
  json: {
    config_valid: true,
    has_systems_resume: true,
    has_mechanical_resume: true,
    has_controls_resume: true,
    systems_resume_chars: String(cfg.systems_resume_text || '').length,
    mechanical_resume_chars: String(cfg.mechanical_resume_text || '').length,
    controls_resume_chars: String(cfg.controls_resume_text || '').length,
  },
}];

/**
 * n8n Code node — Workflow B
 * Remove jobs whose title/JD matches config blocklist (ITAR, citizenship, etc.)
 */

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function splitTerms(value) {
  return clean(value)
    .split(/[,;|\n]/)
    .map((term) => clean(term).toLowerCase())
    .filter(Boolean);
}

const defaultBlocklist = [
  'itar',
  'export control',
  'u.s. citizen',
  'us citizen',
  'united states citizen',
  'citizenship required',
  'must be a citizen',
  'must be a u.s. citizen',
  'active secret clearance',
  'secret clearance',
  'top secret clearance',
  'ability to obtain clearance',
];

const staticData = $getWorkflowStaticData('global');
const configured = splitTerms(staticData.rankingConfig?.blocklist || '');
const blocklist = configured.length ? configured : defaultBlocklist;

function isRestricted(job) {
  const haystack = clean([
    job.title,
    job.full_jd,
    job.location,
    job.company,
  ].join(' ')).toLowerCase();

  return blocklist.some((term) => haystack.includes(term));
}

const out = [];

for (const item of $input.all()) {
  const job = item.json || {};
  if (isRestricted(job)) continue;
  out.push(item);
}

return out;

